WITH with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM transactions), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT account_id, merchant, PERCENTILE_APPROX(amount, 0.95) AS amount_p95, ROUND(AVG(amount), 2) AS avg_amount, COUNT_IF(txn_type = 'FEE') AS fee_events, GROUPING(account_id) AS grouping_id FROM sessionized GROUP BY GROUPING SETS ((account_id, merchant), (account_id)) ORDER BY avg_amount DESC NULLS LAST;
